WITH filtered AS (SELECT *, UPPER(event_type) AS event_type_upper, CASE WHEN duration_sec >= 412 THEN 'High' WHEN duration_sec >= 188 THEN 'Medium' ELSE 'Low' END AS duration_sec_tier FROM web_events WHERE event_time > TIMESTAMP '2023-07-17 17:00:00' AND page IS NOT NULL) SELECT s.id, s.session_id, s.event_type, s.event_time, s.duration_sec, s.duration_sec_tier, p.device FROM filtered s LEFT JOIN sessions p ON s.session_id = p.id;
